PageHandlerAsyncWaiter::PageHandlerAsyncWaiter(
    PageHandler* proxy) : proxy_(proxy) {}

PageHandlerAsyncWaiter::~PageHandlerAsyncWaiter() = default;

void PageHandlerAsyncWaiter::InstallSystemExtensionFromDownloadsDir(
    const ::base::SafeBaseName& system_extension_dir_name, bool* out_success) {
  base::RunLoop loop;
  proxy_->InstallSystemExtensionFromDownloadsDir(std::move(system_extension_dir_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::InstallSystemExtensionFromDownloadsDir(
    const ::base::SafeBaseName& system_extension_dir_name) {
  bool async_wait_result;
  InstallSystemExtensionFromDownloadsDir(std::move(system_extension_dir_name),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::IsSystemExtensionInstalled(
    bool* out_is_installed) {
  base::RunLoop loop;
  proxy_->IsSystemExtensionInstalled(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_is_installed
,
             bool is_installed) {*out_is_installed = std::move(is_installed);
            loop->Quit();
          },
          &loop,
          out_is_installed));
  loop.Run();
}

bool PageHandlerAsyncWaiter::IsSystemExtensionInstalled(
    ) {
  bool async_wait_result;
  IsSystemExtensionInstalled(&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::UninstallSystemExtension(
    ) {
  base::RunLoop loop;
  proxy_->UninstallSystemExtension(
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








